MAGIC = 0x0F1DB5BB
MAX_FILE_SIZE = 65536
MAX_RECORDS = 8


def _u16le(data, offset):
    return data[offset] | (data[offset + 1] << 8)


def _u32le(data, offset):
    return (
        data[offset]
        | (data[offset + 1] << 8)
        | (data[offset + 2] << 16)
        | (data[offset + 3] << 24)
    )


def parse(data: bytes):
    try:
        size = len(data)
        if size < 7 or size > MAX_FILE_SIZE:
            return None
        if _u32le(data, 0) != MAGIC:
            return None
        if data[4] != 0x81:
            return None

        offset = 5
        record_count = _u16le(data, offset)
        offset += 2
        if record_count > MAX_RECORDS:
            return None

        sequence = _u32le(data, offset)
        offset += 4

        records = []
        for _ in range(record_count):
            if size - offset < 6:
                return None
            code = data[offset]
            stock = data[offset + 1]
            priority = _u16le(data, offset + 2)
            timestamp = _u16le(data, offset + 4)
            offset += 6
            records.append(
                {
                    "code": code,
                    "priority": priority,
                    "stock": stock,
                    "timestamp": timestamp,
                }
            )

        if offset != size:
            return None

        return {"header": {"sequence": sequence}, "records": records}
    except Exception:
        return None
