    if data[0:4] != b"\xa8\x30\x28\x20":
        return None
    if data[4] != 0x0A:
        return None
    offset = 5

    def read(width, big_endian=False):
        nonlocal offset
        if offset > end or width > end - offset:
            return None
        chunk = data[offset:offset + width]
        offset += width
        return int.from_bytes(chunk, "big" if big_endian else "little")

    record_count = read(4)
    if record_count is None or record_count > 8:
        return None
    code = read(2)
    if code is None:
        return None
    balance = read(1)
    if balance is None:
        return None
    records = []
    for _ in range(record_count):
        region = read(1)
        if region is None:
            return None
        status = read(4)
        if status is None:
            return None
        records.append({"region": region, "status": status})
    if offset != end:
        return None
    return {"header": {"balance": balance, "code": code}, "records": records}
