    data = bytes(data)
    end = len(data)
    if end < 7 or end > 65536:
        return None

    if data[0:4] != b"\x34\xde\x90\xea":
        return None
    if data[4] != 0x95:
        return None

    offset = 5

    def read_uint(width):
        nonlocal offset
        if offset > end or width > end - offset:
            return None
        value = int.from_bytes(data[offset:offset + width], "little")
        offset += width
        return value

    record_count = read_uint(2)
    if record_count is None or record_count > 8:
        return None

    sku = read_uint(4)
    if sku is None:
        return None
    priority = read_uint(4)
    if priority is None:
        return None

    records = []
    for _ in range(record_count):
        account_id = read_uint(2)
        if account_id is None:
            return None
        score = read_uint(1)
        if score is None:
            return None
        count = read_uint(4)
        if count is None:
            return None
        status = read_uint(2)
        if status is None:
            return None
        sku_value = read_uint(2)
        if sku_value is None:
            return None
        records.append({
