def parse(data: bytes):
    """Parse the binary format understood by ``reader``.

    Returns the represented dictionary, or ``None`` when the input is not a
    well-formed file.
    """
    size = len(data)
    if size > 65536 or size < 9:
        return None

    # Fixed 5-byte header: little-endian magic followed by version byte.
    if data[:4] != b"\x7b\x8f\x71\x1b" or data[4] != 0x5A:
        return None

    record_count = int.from_bytes(data[5:9], "little")
    if record_count > 8:
        return None

    offset = 9

    def read_number(width):
        nonlocal offset
        if offset + width > size:
            return None
        value = int.from_bytes(data[offset:offset + width], "little")
        offset += width
        return value

    account_id = read_number(2)
    if account_id is None:
        return None
    score = read_number(4)
    if score is None:
        return None

    records = []
    for _ in range(record_count):
        category = read_number(2)
        if category is None:
            return None
        count = read_number(2)
        if count is None:
            return None
        flags = read_number(2)
        if flags is None:
            return None
        amount = read_number(1)
        if amount is None:
            return None
        status = read_number(2)
        if status is None:
            return None

        records.append({
            "amount": amount,
            "category": category,
            "count": count,
            "flags": flags,
            "status": status,
        })

    if offset != size:
        return None

    return {
        "header": {
            "account_id": account_id,
            "score": score,
        },
        "records": records,
    }
