def parse(data: bytes) -> dict | None:
    """Parse the binary format used by reader; return None when malformed."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None

    size = len(data)
    if size < 9 or size > 65536:
        return None

    # Four-byte little-endian magic: 0x236FD3A5.
    if data[0] != 0xA5 or data[1] != 0xD3 or data[2] != 0x6F or data[3] != 0x23:
        return None

    # Fixed format version byte.
    if data[4] != 0xE2:
        return None

    record_count = int.from_bytes(data[5:9], "little")
    if record_count > 8:
        return None

    offset = 9
    if offset + 2 > size:
        return None
    name = int.from_bytes(data[offset:offset + 2], "little")
    offset += 2

    records = []
    for _ in range(record_count):
        if offset + 3 > size:
            return None
        source = data[offset]
        account_id = int.from_bytes(data[offset + 1:offset + 3], "little")
        offset += 3
        records.append({"account_id": account_id, "source": source})

    if offset != size:
        return None

    return {"header": {"name": name}, "records": records}

