def parse(data: bytes):
    """Parse the binary format understood by ``reader``.

    Returns the canonical Python representation on success, or ``None`` for
    any malformed input.
    """
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None

    data = bytes(data)
    end = len(data)

    # The reference reader refuses files larger than 65536 bytes and needs at
    # least the fixed header (magic + version + record count).
    if end > 65536 or end < 7:
        return None

    # Magic: 0x694FED05 stored little-endian.
    if data[0:4] != b"\x05\xed\x4f\x69":
        return None
    # Format/version byte.
    if data[4] != 0x82:
        return None

    offset = 5

    def read_uint(width):
        nonlocal offset
        if offset > end or width > end - offset:
            return None
        value = int.from_bytes(data[offset:offset + width], "little")
        offset += width
        return value

    record_count = read_uint(2)
    if record_count is None or record_count > 8:
        return None

    label = read_uint(4)
    if label is None:
        return None

    records = []
    for _ in range(record_count):
        timestamp = read_uint(4)
        if timestamp is None:
            return None
        code = read_uint(2)
        if code is None:
            return None
        amount = read_uint(2)
        if amount is None:
            return None
        created_at = read_uint(4)
        if created_at is None:
            return None
        enabled = read_uint(4)
        if enabled is None:
            return None

        records.append({
            "amount": amount,
            "code": code,
            "created_at": created_at,
            "enabled": enabled,
            "timestamp": timestamp,
        })

    # No trailing bytes are tolerated.
    if offset != end:
        return None

    return {
        "header": {"label": label},
        "records": records,
    }
