random.seed(1)
def run_reader(data):
    with tempfile.NamedTemporaryFile(delete=False) as f:
        f.write(data); p=f.name
    try:
        r=subprocess.run(['./reader',p],capture_output=True,text=True)
        out=r.stdout
        return None if out.strip()=='INVALID' or r.returncode!=0 else out.rstrip('\n')
    finally:
