    exp=run_reader(data)
    got=parser.parse(data)
    if exp is None:
        if got is not None:
            print("MISMATCH expected invalid", data.hex(), got); return False
    else:
        if got is None:
            print("MISMATCH expected valid", data.hex(), exp); return False
        g=json.dumps(got,separators=(',',':'))
        if g!=exp:
            print("MISMATCH json", data.hex(), g, exp); return False
